create or replace view public.powerhouse_resource_impact_v1 with (security_invoker=true) as select u.usage_id, coalesce(nullif(u.metadata->>'tenant_id',''),'canonical') as tenant_id, u.source, u.usage_type as resource_type, u.unit, u.amount, u.occurred_at, f.factor_id, f.methodology, f.confidence, case when f.factor_id is null then 'unknown_factor' else 'calculated' end as calculation_status, case when f.factor_id is null or f.energy_kwh is null then null else (u.amount / f.quantity_basis) * f.energy_kwh end as energy_kwh, case when f.factor_id is null or f.co2e_kg is null then null else (u.amount / f.quantity_basis) * f.co2e_kg end as co2e_kg, case when f.factor_id is null or f.water_liters is null then null else (u.amount / f.quantity_basis) * f.water_liters end as water_liters from public.brain_budget_usage u left join lateral (select x.* from public.powerhouse_resource_factors x where x.resource_type=u.usage_type and x.unit=u.unit and (x.source is null or x.source=u.source) and x.valid_from<=u.occurred_at::date and (x.valid_to is null or x.valid_to>=u.occurred_at::date) order by (x.source is not null) desc, x.valid_from desc limit 1) f on true where u.entry_kind='USAGE' and u.source <> 'make' and coalesce(u.metadata->>'synthetic','false') <> 'true'; revoke all on public.powerhouse_resource_impact_v1 from anon, authenticated;
